    function refreshPreview() { const pv = $('.preview'); if (pv) { $('b', pv).textContent = CF.name || 'Name'; $('small', pv).textContent = `${CF.symbol || 'TICKER'} · opens at ${fmtNum(E.openMcapHype)} ${Q} · ${C.chain.name}`; if (!CF.image) $('img', pv).src = APP.defaultImg(CF.symbol || '?', CF.name); } const go = $('#c-go'); if (go && live && APP.W.connected) go.textContent = `Launch for ${E.launchFeeHype} ${Q}${parseFloat(CF.devBuy) > 0 ? ' + ' + CF.devBuy + ' ' + Q : ''}`; }
    $('#c-go').onclick = () => { if (!APP.W.connected) return APP.W.connect(); if (!CF.name || !CF.symbol) return APP.toast('Name and ticker required', 'err'); if (!CF.image) return APP.toast('Add a logo', 'err'); if (/https?:\/\/|www\.|\.[a-z]{2,}\//i.test(CF.description)) return APP.toast('No links in the description', 'err'); act(async () => { const r = await DATA.launch({ name: CF.name, symbol: CF.symbol, image: CF.image, description: CF.description, x: CF.x, telegram: CF.telegram, website: CF.website, creatorTaxBps: CF.creatorTaxBps, buyback: CF.buyback, devBuy: parseFloat(CF.devBuy) || 0 }); APP.toast('Launched', 'ok'); Object.assign(CF, { name: '', symbol: '', image: '', description: '', x: '', telegram: '', website: '', creatorTaxBps: 0, buyback: false, devBuy: '' }); if (r && r.addr) location.hash = '#/token/' + r.addr; else location.hash = '#/'; }); };
